#!/usr/bin/env bash
# Environment parity probe. Read-only; safe to run on any runner. No set -e: every section is best-effort.
# Usage: bash guest-probe.sh > probe-<target>.txt 2>&1
export LC_ALL=C
S() { printf '\n=== %s ===\n' "$1"; }
C() { printf '$ %s\n' "$*"; timeout 20 "$@" 2>&1 | head -${LINES_MAX:-200}; }
SH() { printf '$ %s\n' "$1"; timeout 30 bash -c "$1" 2>&1 | head -${LINES_MAX:-200}; }

S meta; SH 'date -u +%FT%TZ; hostname; id; echo PID1=$(cat /proc/1/comm); echo uptime=$(cut -d" " -f1 /proc/uptime)'
S os; SH 'cat /etc/os-release; cat /etc/lsb-release 2>/dev/null; cat /etc/issue; echo ImageOS=$ImageOS ImageVersion=$ImageVersion; ls /imagegeneration 2>&1; cat /imagegeneration/imagedata.json 2>/dev/null | head -20'
S kernel; SH 'uname -a; cat /proc/version; cat /proc/cmdline; ls /lib/modules 2>&1; zcat /proc/config.gz 2>/dev/null | grep -E "^CONFIG_(USER_NS|NAMESPACES|PID_NS|NET_NS|UTS_NS|IPC_NS|CGROUPS|CGROUP_[A-Z_]+|MEMCG|BPF_SYSCALL|BPF_JIT|OVERLAY_FS|FUSE_FS|VIRTIO_[A-Z_]+|NETFILTER|NF_TABLES|NF_CONNTRACK|IP_NF_[A-Z_]+|BRIDGE|VETH|VXLAN|TUN|WIREGUARD|IPV6|INOTIFY_USER|FANOTIFY|SECCOMP|SECURITY_[A-Z_]+|MAGIC_SYSRQ|NET_SCHED|NET_CLS_[A-Z_]+|TMPFS_[A-Z_]+|EXT4_FS|XFS_FS|BTRFS_FS|SQUASHFS|EROFS_FS|ISO9660_FS|NFS_FS|CIFS|9P_FS|KVM|BINFMT_[A-Z_]+|SYSVIPC|POSIX_MQUEUE|HUGETLB[A-Z_]*|TRANSPARENT_HUGEPAGE|NUMA|PREEMPT[A-Z_]*|HZ|NO_HZ[A-Z_]*|X86_[A-Z_]*PAT|KEYS|AUDIT|PERF_EVENTS|FTRACE|KPROBES|DEBUG_INFO_BTF)=" | sort'
S cpu_mem; SH 'nproc; lscpu | head -30; free -m; cat /proc/meminfo | head -8; swapon --show; cat /sys/kernel/mm/transparent_hugepage/enabled 2>&1'
S cpu_flags; SH 'grep -m1 flags /proc/cpuinfo | tr " " "\n" | grep -E "^(avx|avx2|avx512[a-z_]*|sse4_2|aes|pclmulqdq|bmi1|bmi2|fma|sha_ni|vmx|svm|hypervisor|rdrand|rdseed|constant_tsc|invtsc|x2apic)$" | tr "\n" " "'
S devices; SH 'ls -la /dev | head -80; ls /dev/kvm /dev/fuse /dev/net/tun /dev/loop-control /dev/vhost-net /dev/dri /dev/snd /dev/ttyS0 /dev/hwrng /dev/urandom /dev/shm 2>&1'
S pci_usb; SH 'lspci 2>&1 | head -20; lsusb 2>&1 | head -5; ls /sys/bus/pci/devices 2>&1 | head; ls /sys/bus/virtio/devices 2>&1; ls /sys/class/net; ls /sys/class/block; cat /sys/class/dmi/id/sys_vendor /sys/class/dmi/id/product_name 2>&1'
S block_fs; SH 'lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,RO,ROTA 2>&1; df -hT -x tmpfs -x devtmpfs; df -i / /tmp /home 2>&1; findmnt -A -o TARGET,SOURCE,FSTYPE,OPTIONS 2>&1 | head -80'
S mounts_raw; SH 'cat /proc/mounts | head -80; cat /proc/filesystems | tr "\n" " "'
S io_sched; SH 'for d in /sys/block/*; do echo $d $(cat $d/queue/scheduler 2>&1) rot=$(cat $d/queue/rotational 2>&1) ra=$(cat $d/queue/read_ahead_kb 2>&1); done'
S cgroup; SH 'stat -fc %T /sys/fs/cgroup; cat /proc/self/cgroup; cat /sys/fs/cgroup/cgroup.controllers 2>&1; cat /sys/fs/cgroup/cgroup.subtree_control 2>&1; cat /sys/fs/cgroup/memory.max /sys/fs/cgroup/cpu.max /sys/fs/cgroup/pids.max 2>&1'
S limits; SH 'ulimit -a; cat /proc/self/limits'
S sysctl; SH 'sysctl -a 2>/dev/null | grep -E "^(fs\.(file-max|nr_open|inotify\.[a-z_]+|aio-max-nr|protected_[a-z]+|suid_dumpable)|kernel\.(pid_max|threads-max|sysrq|core_pattern|randomize_va_space|yama\.ptrace_scope|unprivileged_userns_clone|apparmor_restrict_unprivileged_userns|unprivileged_bpf_disabled|panic|shmmax|shmall|sem|msgmax|printk|hostname|domainname|perf_event_paranoid|kptr_restrict)|vm\.(max_map_count|swappiness|overcommit_memory|overcommit_ratio|dirty_[a-z_]+|min_free_kbytes|mmap_min_addr)|net\.(core\.(somaxconn|rmem_max|wmem_max|netdev_max_backlog|default_qdisc)|ipv4\.(ip_forward|ip_local_port_range|tcp_[a-z_]+|ping_group_range|conf\.all\.rp_filter|conf\.all\.forwarding)|ipv6\.conf\.all\.disable_ipv6|netfilter\.nf_conntrack_max|bridge\.bridge-nf-call-iptables))" | sort'
S security; SH 'cat /proc/self/status | grep -E "Cap|Seccomp|NoNewPrivs|Uid|Gid|Groups"; capsh --print 2>&1 | head -8; aa-status 2>&1 | head -5; cat /sys/kernel/security/lsm 2>&1; getenforce 2>&1; cat /proc/sys/kernel/unprivileged_userns_clone /proc/sys/user/max_user_namespaces 2>&1; unshare -Ur true 2>&1 && echo userns-ok; unshare -n true 2>&1 && echo netns-ok'
S users_sudo; SH 'id runner 2>&1; getent group docker sudo; sudo -n true 2>&1 && echo sudo-nopasswd-ok; sudo -n -l 2>&1 | head -5; ls -ld /home/* /home/runner /opt /opt/* /usr/local /usr/local/bin 2>&1; umask; echo $HOME $USER $SHELL; getent passwd | grep -E "runner|postgres|mysql|docker|vsts|builder|ubuntu" '
S env; SH 'env | sort | sed -E "s/(TOKEN|SECRET|KEY|PASSWORD|AUTH)=.*/\1=<redacted>/I" | head -120'
S path_tools; SH 'echo $PATH | tr ":" "\n"; ls /usr/local/bin | head -100; ls /opt | head -50; ls /opt/hostedtoolcache 2>&1 | head -30'
S runner_layout; SH 'ls -la /home/runner /home/runner/work /home/runner/runners /home/runner/.local /home/runner/.config 2>&1 | head -50; ls -la /home/runner/work/_temp /home/runner/work/_tool 2>&1 | head; echo RUNNER_TOOL_CACHE=$RUNNER_TOOL_CACHE AGENT_TOOLSDIRECTORY=$AGENT_TOOLSDIRECTORY RUNNER_TEMP=$RUNNER_TEMP RUNNER_WORKSPACE=$RUNNER_WORKSPACE'
S systemd; SH 'ps -o pid,comm,args -p 1; systemctl is-system-running 2>&1; systemctl --failed --no-legend 2>&1 | head -20; systemctl list-units --type=service --state=running --no-legend 2>&1 | head -40; systemctl list-unit-files --state=enabled --no-legend 2>&1 | head -60; systemd-analyze 2>&1 | head -3; loginctl list-sessions 2>&1 | head; busctl --no-pager list 2>&1 | head -5'
S timers_cron; SH 'systemctl list-timers --all --no-legend 2>&1 | head -20; ls /etc/cron.* 2>&1 | head -20; crontab -l 2>&1 | head -3'
S processes; SH 'ps -eo pid,ppid,user,comm,%mem,args --sort=-%mem | head -40; ls /proc | grep -cE "^[0-9]+$"'
S network; SH 'ip -br addr; ip -br link; ip route; ip -6 route; ip -d link show 2>/dev/null | grep -E "mtu|qdisc" | head; cat /etc/hosts; cat /etc/resolv.conf; ls -la /etc/resolv.conf; cat /etc/nsswitch.conf | grep -E "^hosts"; cat /etc/hostname; cat /etc/gai.conf 2>/dev/null | grep -v "^#" | head -5'
S dns; SH 'resolvectl status 2>&1 | head -25; getent hosts localhost postgres.localhost foo.localhost; getent ahosts github.com | head -3; getent ahostsv6 localhost; (time getent hosts github.com) 2>&1 | grep real; ss -ltnup 2>&1 | head -30'
S connectivity; SH 'for u in https://github.com https://api.github.com https://registry.npmjs.org https://pypi.org https://ghcr.io https://index.docker.io/v2/ https://objects.githubusercontent.com https://api.nuget.org/v3/index.json https://static.crates.io http://archive.ubuntu.com https://azure.archive.ubuntu.com ; do printf "%s " $u; curl -sS -o /dev/null -m 15 -w "%{http_code} dns=%{time_namelookup} conn=%{time_connect} tls=%{time_appconnect} total=%{time_total} ip=%{remote_ip}\n" $u 2>&1; done; curl -4 -sS -m 10 https://ifconfig.me 2>&1 | head -1; curl -6 -sS -m 10 https://ifconfig.me 2>&1 | head -1; ping -c1 -W2 1.1.1.1 2>&1 | tail -2; ping -c1 -W2 github.com 2>&1 | tail -2; curl -sS -m5 -H "Metadata: true" "http://169.254.169.254/metadata/instance?api-version=2021-02-01" 2>&1 | head -c 200'
S ntp_time; SH 'timedatectl 2>&1 | head -12; date; echo TZ=$TZ; cat /etc/timezone 2>&1; locale 2>&1; cat /sys/devices/system/clocksource/clocksource0/current_clocksource 2>&1; hwclock --show 2>&1 | head -2'
S entropy_rand; SH 'cat /proc/sys/kernel/random/entropy_avail /proc/sys/kernel/random/poolsize; cat /sys/devices/virtual/misc/hw_random/rng_current 2>&1'
S docker; SH 'docker version 2>&1 | head -30; docker info 2>&1 | head -60; docker compose version; docker buildx version; docker buildx ls 2>&1 | head; docker network ls; docker images 2>&1 | head -20; cat /etc/docker/daemon.json 2>&1; ls -la /var/lib/docker /var/lib/containerd 2>&1 | head; docker run --rm hello-world 2>&1 | head -5; ls -l /var/run/docker.sock; id | grep -o docker'
S docker_net; SH 'docker network create probe-net >/dev/null 2>&1; docker run --rm --network probe-net alpine sh -c "cat /etc/resolv.conf; nslookup github.com | head -6; wget -q -O- -T5 https://api.github.com 2>&1 | head -c 100" 2>&1 | head -20; docker network rm probe-net >/dev/null 2>&1; docker run --rm alpine cat /etc/resolv.conf 2>&1; docker run --rm --add-host=probe.localhost:127.0.0.1 alpine getent hosts probe.localhost 2>&1'
S docker_features; SH 'docker run --rm --privileged alpine sh -c "mount -t tmpfs none /mnt && echo priv-mount-ok" 2>&1; docker run --rm --security-opt seccomp=unconfined alpine sh -c "echo ok" 2>&1 | head -2; docker run --rm -v /var/run/docker.sock:/var/run/docker.sock alpine ls /var/run/docker.sock 2>&1; docker run --rm --platform linux/arm64 alpine uname -m 2>&1 | head -2; docker run --rm --memory 100m --cpus 0.5 alpine echo limits-ok 2>&1 | head -2; docker run --rm --init alpine echo init-ok 2>&1|head -2; docker run --rm --shm-size 512m alpine df -h /dev/shm 2>&1 | tail -1'
S container_runtimes; SH 'for c in podman buildah skopeo containerd ctr runc crun nerdctl kubectl kind minikube helm kustomize; do printf "%s: " $c; ($c --version 2>&1 || $c version 2>&1) | head -1; done; which -a docker-compose'
S languages; SH 'for c in "node --version" "npm --version" "yarn --version" "pnpm --version" "bun --version" "deno --version" "python3 --version" "python --version" "pip --version" "pipx --version" "uv --version" "poetry --version" "go version" "rustc --version" "cargo --version" "rustup --version" "ruby --version" "gem --version" "bundle --version" "java -version" "javac -version" "mvn --version" "gradle --version" "ant -version" "dotnet --version" "php --version" "composer --version" "perl --version" "swift --version" "kotlin -version" "R --version" "julia --version" "erl -version" "elixir --version" "ghc --version" "cabal --version" "stack --version" "sbt --version" "clang --version" "gcc --version" "g++ --version" "cmake --version" "make --version" "ninja --version" "bazel --version" "meson --version" "pkg-config --version" "nasm -v" "gfortran --version" "mise --version" "asdf --version"; do printf "%-24s " "$c"; (timeout 10 $c 2>&1 | head -1); done'
S cli_tools; SH 'for c in "git --version" "git lfs version" "gh --version" "curl --version" "wget --version" "jq --version" "yq --version" "xmllint --version" "tar --version" "zip -v" "unzip -v" "7z" "zstd --version" "xz --version" "bzip2 --help" "rsync --version" "ssh -V" "openssl version" "gpg --version" "sqlite3 --version" "psql --version" "mysql --version" "mongod --version" "redis-server --version" "nginx -v" "apache2 -v" "haproxy -v" "az --version" "aws --version" "gcloud --version" "terraform --version" "packer --version" "ansible --version" "pulumi version" "sops --version" "age --version" "vim --version" "nano --version" "less --version" "tree --version" "htop --version" "lsof -v" "strace -V" "ltrace -V" "gdb --version" "perf --version" "tcpdump --version" "nc -h" "nmap --version" "dig -v" "nslookup -version" "iptables --version" "nft --version" "ip -V" "sudo --version" "zsh --version" "fish --version" "bash --version" "dash -V" "parallel --version" "shellcheck --version" "hadolint --version" "actionlint --version" "direnv --version" "just --version" "task --version" "firefox --version" "google-chrome --version" "chromium --version" "chromedriver --version" "geckodriver --version" "microsoft-edge --version" "playwright --version" "xvfb-run --help" "fc-list" "convert --version" "ffmpeg -version" "sox --version" "tesseract --version" "unixodbc" "odbcinst --version" "snap --version" "flatpak --version" "systemctl --version" "tmux -V" "screen --version" "ccache --version" "sccache --version" "mold --version" "lld --version" "kacache --version" "npx --version"; do printf "%-26s " "$c"; (timeout 10 $c 2>&1 | head -1 | cut -c1-110); done'
S which_missing; SH 'for c in git gh curl wget jq yq node npm python3 pip3 go rustc cargo ruby java javac mvn gradle dotnet php docker docker-compose podman buildah skopeo kubectl helm terraform aws az gcloud psql mysql sqlite3 redis-server nginx apache2 firefox google-chrome chromedriver geckodriver xvfb-run zsh fish clang gcc g++ make cmake ninja pkg-config unzip zip 7z zstd xz sudo openssl gpg rsync ssh nc dig ping traceroute iptables nft ip ss lsof strace tmux screen htop vim nano tree parallel shellcheck ccache bazel; do command -v $c >/dev/null 2>&1 && echo "HAVE $c" || echo "MISSING $c"; done | sort | uniq -c | sort -rn | head -0; for c in git gh curl wget jq yq node npm python3 pip3 go rustc cargo ruby java javac mvn gradle dotnet php docker podman buildah skopeo kubectl helm terraform aws az gcloud psql mysql sqlite3 redis-server nginx apache2 firefox google-chrome chromedriver geckodriver xvfb-run zsh clang gcc g++ make cmake ninja pkg-config unzip zip 7z zstd xz sudo openssl gpg rsync ssh nc dig ping traceroute iptables nft ip ss lsof strace tmux screen vim nano tree parallel shellcheck ccache bazel; do command -v $c >/dev/null 2>&1 || printf "MISSING:%s " $c; done; echo'
S packages; SH 'dpkg -l 2>/dev/null | wc -l; dpkg-query -W -f="${Package} ${Version}\n" 2>/dev/null | sort > /tmp/probe-dpkg.txt; wc -l /tmp/probe-dpkg.txt; cat /tmp/probe-dpkg.txt' | head -3000
S apt_snap; SH 'cat /etc/apt/sources.list /etc/apt/sources.list.d/* 2>&1 | grep -vE "^#|^$" | head -40; ls /etc/apt/apt.conf.d | head -30; cat /etc/apt/apt.conf.d/99* 2>&1 | head -20; snap list 2>&1 | head -5; pip3 list 2>/dev/null | head -60; npm ls -g --depth=0 2>&1 | head -40; gem list 2>/dev/null | head -20; cargo install --list 2>&1 | head -20; pipx list 2>&1 | head -20'
S toolcache; SH 'ls /opt/hostedtoolcache/* 2>&1 | head -60; ls ~/.cargo/bin ~/.rustup/toolchains ~/.nvm ~/.pyenv ~/.local/bin ~/.dotnet ~/.sdkman 2>&1 | head -40; ls /usr/share/dotnet /usr/lib/jvm /usr/local/lib/node_modules /usr/local/share /usr/local/n 2>&1 | head -40'
S runner_images_toolsets; SH 'ls /imagegeneration/installers 2>&1 | head; cat /etc/environment; cat /etc/profile.d/*.sh 2>&1 | head -60; cat /etc/default/locale 2>&1; ls /etc/sudoers.d; sudo -n cat /etc/sudoers.d/* 2>&1 | head -10'
S shell_rc; SH 'cat ~/.bashrc 2>&1 | tail -20; cat ~/.profile 2>&1 | tail -10; ls -la ~ | head -40; cat ~/.gitconfig 2>&1; git config --system -l 2>&1; git config --global -l 2>&1; ls -la /etc/ssh 2>&1 | head; ssh-keyscan -T3 github.com 2>&1 | head -2; cat ~/.ssh/known_hosts 2>&1 | head -3'
S fs_semantics; SH 'cd /tmp && rm -rf fsprobe && mkdir fsprobe && cd fsprobe && touch A a && ls | wc -l; echo case-sensitive=$([ $(ls | wc -l) = 2 ] && echo yes || echo no); ln -s a sym && echo symlink-ok; ln a hard && echo hardlink-ok; mkfifo f && echo fifo-ok; python3 -c "import socket,os;s=socket.socket(socket.AF_UNIX);s.bind(\"u.sock\");print(\"unix-socket-ok\")" 2>&1; touch -d "2001-01-01" t && stat -c %y t; setfattr -n user.x -v 1 a 2>&1 && getfattr -n user.x a 2>&1 | tail -1; chmod 4755 a && stat -c %A a; mknod n c 1 3 2>&1 | head -1; fallocate -l 100M big 2>&1 && echo fallocate-ok; dd if=/dev/zero of=d bs=1M count=64 conv=fsync 2>&1 | tail -1; flock -n . true && echo flock-ok; cd /; rm -rf /tmp/fsprobe'
S fs_perf; SH 'cd /tmp && dd if=/dev/zero of=perf bs=1M count=512 conv=fdatasync 2>&1 | tail -1; dd if=perf of=/dev/null bs=1M 2>&1 | tail -1; rm -f perf; mkdir -p pf && cd pf && time (for i in $(seq 1 3000); do echo x > f$i; done) 2>&1 | grep real; time (find . | wc -l) 2>&1 | grep real; cd .. && rm -rf pf; df -h /tmp /home /var/lib/docker 2>&1; for d in /home/runner /home/runner/work /var/lib/docker; do [ -d $d ] && (cd $d && dd if=/dev/zero of=.perf bs=1M count=256 conv=fdatasync 2>&1 | tail -1; rm -f .perf); done'
S cpu_perf; SH 'time (python3 -c "import hashlib,time;h=hashlib.sha256();[h.update(b\"x\"*1048576) for _ in range(512)]") 2>&1 | grep real; time (for i in $(seq 1 200); do /bin/true; done) 2>&1 | grep real; time (echo "scale=2000; 4*a(1)" | bc -l >/dev/null) 2>&1 | grep real; which fio sysbench stress-ng 2>&1'
S mem_behavior; SH 'cat /proc/sys/vm/overcommit_memory; python3 -c "
import mmap
m=mmap.mmap(-1,1<<30)
print(\"1GiB anon mmap ok\")" 2>&1; ulimit -v; cat /sys/fs/cgroup/memory.high 2>&1; dmesg 2>&1 | tail -3'
S gpu_display; SH 'ls /dev/dri /dev/nvidia* 2>&1 | head -3; nvidia-smi 2>&1 | head -2; echo DISPLAY=$DISPLAY WAYLAND=$WAYLAND_DISPLAY; which Xvfb xvfb-run Xorg 2>&1; fc-list 2>/dev/null | wc -l'
S browsers; SH 'google-chrome --version; chromium --version; firefox --version; microsoft-edge --version; chromedriver --version; geckodriver --version; ls ~/.cache/ms-playwright 2>&1 | head; echo CHROME_BIN=$CHROME_BIN CHROMEWEBDRIVER=$CHROMEWEBDRIVER GECKOWEBDRIVER=$GECKOWEBDRIVER EDGEWEBDRIVER=$EDGEWEBDRIVER'
S git_clone; SH 'cd /tmp && rm -rf gc && (time git clone --depth 1 https://github.com/actions/checkout gc) 2>&1 | tail -5; rm -rf gc; git config --global --get-regexp "safe|credential|url" 2>&1 | head'
S serv_ports; SH 'ss -ltnp 2>&1 | head -20; for p in 22 80 443 3306 5432 6379 27017 5672 9200 8080; do (echo > /dev/tcp/127.0.0.1/$p) 2>/dev/null && echo "listening:$p"; done; cat /proc/sys/net/ipv4/ip_local_port_range'
S preinstalled_services; SH 'systemctl status postgresql mysql mongod redis-server nginx apache2 docker containerd ssh cron rsyslog snapd unattended-upgrades walinuxagent waagent cloud-init hv-kvp-daemon 2>&1 | grep -E "^(●|○|Unit|Loaded|Active)|could not be found" | head -50; ls /etc/init.d 2>&1 | head -40'
S misc; SH 'cat /etc/machine-id | head -c 8; echo; cat /etc/fstab 2>&1; cat /proc/sys/kernel/hostname; ulimit -n; cat /proc/sys/fs/file-nr; cat /proc/loadavg; cat /proc/pressure/cpu 2>&1 | head -1; ls /var/log | head -30; ls -la /tmp | head -10; df -h /dev/shm /run /run/lock /tmp 2>&1'
S done; echo probe-complete
